SHEET_DATA_COMPAT["Расшифровка совместимости"].literals["B28"] = "Ценность пары";
SHEET_DATA_COMPAT["Расшифровка совместимости"].formulas["C28"] = function(SHEET, cell, rangeVals) { return cell("Диаграмма совместимости", "D188"); };
SHEET_DATA_COMPAT["Расшифровка совместимости"].formulas["D28"] = function(SHEET, cell, rangeVals) { return fn_VLOOKUP(cell(SHEET, "C28"), rangeVals("Данные совместимости", "A194", "B215"), 2, 0); };
SHEET_DATA_COMPAT["Данные совместимости"].literals["A1"] = "1.Для чего встретилась пара";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A2"] = 1;
SHEET_DATA_COMPAT["Данные совместимости"].literals["A3"] = 2;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B3"] = "Такая пара встретилась, чтобы научиться заботиться друг о друге и дарить взаимное внимание. Важны открытость и доверие — тогда партнёры понимают друг друга без слов, интуитивно. Важно поддерживать в доме уютную атмосферу и заботиться о своих потребностях. Не стоит откладывать рождение детей — всё это укрепляет союз.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A4"] = 3;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B4"] = "В этой паре царят лёгкие, почти детские отношения — партнёры смотрят друг на друга сквозь «розовые очки». Отношения складываются наиболее благополучно, когда оба состоялись как личности и готовы продолжить род, воспитывая детей.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A5"] = 4;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B5"] = "Пара стремится к материальному успеху — оба растут по карьерной лестнице, развиваются профессионально. Нацелены на приумножение того, что имеют, включая жильё и бизнес.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A6"] = 5;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B6"] = "Эта пара живёт настоящим моментом, не откладывая жизнь на потом. Любит обустраивать быт. Партнёры слышат друг друга и способны договориться по любому вопросу — их отношения могут стать примером для других.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A7"] = 6;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B7"] = "Эта пара стремится повысить своё положение в обществе, достичь успеха и социальной реализации. Партнёры создают достаток, окружают себя красивыми вещами.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A8"] = 7;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B8"] = "Пара создана для совместного духовного роста — партнёры помогают друг другу решать проблемы, а в союзе рождаются свежие идеи и замыслы.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A9"] = 8;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B9"] = "Перед этой парой стоят вопросы и задачи, ради решения которых она и встретилась. Партнёры многое делают вместе, разделяя обязанности и дополняя друг друга — каждый берёт на себя то, что получается лучше. Прекрасно решают организационные вопросы вместе, могут считать себя идеальным союзом.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A10"] = 9;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B10"] = "Паре важно добиться финансовой стабильности и уверенности в завтрашнем дне. Партнёры гармонично смотрятся вместе, живут в согласии, совершенствуют личные качества и наполняются житейской мудростью.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A11"] = 10;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B11"] = "Этот союз создан, чтобы партнёры почувствовали лёгкость жизни без ограничений, «дышали полной грудью». Во всём сопутствует удача. Партнёры становятся друг другу не только любовниками и супругами, но и настоящими друзьями.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A12"] = 11;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B12"] = "Этот союз образован, чтобы научить партнёров полному взаимопониманию. Для пары характерны душевная близость, общность интересов и взглядов. Активность предпочитают лени и бездействию.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A13"] = 12;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B13"] = "Пара встретилась, чтобы кардинально изменить свои жизни. Оба партнёра сильно отличаются от их прежних избранников.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A14"] = 13;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B14"] = "Партнёры встретились в зрелом возрасте или при ограниченных возможностях здоровья у одного из них, чтобы вместе пройти путь духовного роста и перерождения. В основе этого пути — опыт проживания боли, поэтому важны внутренняя дисциплина и самоконтроль.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A15"] = 14;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B15"] = "Пара встретилась, чтобы изменить мировоззрение друг друга и научиться жить сегодняшним днём. Партнёрам комфортно вместе размышлять, ища собственные истины.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A16"] = 15;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B16"] = "Паре предстоит работать над своими пороками и недостатками через самоконтроль и осознанность. В таком союзе партнёры ставят перед собой большие цели и достигают их.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A17"] = 16;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B17"] = "Пара образована для тихой, спокойной жизни. Партнёры находят друг в друге умиротворение, понимание и поддержку. Любовь в этом союзе подкрепляется поступками, а не только словами.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A18"] = 17;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B18"] = "Пара образовалась, чтобы партнёры совершенствовались вместе. Важно найти свою роль в обществе, расти духовно, работать над внутренними качествами, находить и развивать таланты, помогая друг другу в этом.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A19"] = 18;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B19"] = "Партнёры встретились, чтобы дарить друг другу безусловную веру и поддержку. Паре важно не бояться ставить перед собой масштабные цели и желания.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A20"] = 19;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B20"] = "Пара встретилась, чтобы во всех жизненных вопросах действовать как одна команда, вместе идя к общим целям. Партнёров объединяют схожие интересы — в целом пара ощущает единство душ и гармонично дополняет друг друга.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A21"] = 20;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B21"] = "Встретившись, партнёры понимают, что нашли родную душу, — возникает ощущение давнего знакомства. Этой паре важно жить настоящим моментом, «дышать полной грудью» и пользоваться шансами, которые дарит судьба.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A22"] = 21;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B22"] = "Этой паре важно жить на полную мощь, используя шансы, подаренные судьбой. Пара встретилась, чтобы стать примером прекрасных, близких отношений.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A23"] = 22;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B23"] = "Партнёры встретились, чтобы подарить друг другу искренние отношения, полные чувств, заботы и участия.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A25"] = "2.Как проявляется пара";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A26"] = 1;
SHEET_DATA_COMPAT["Данные совместимости"].literals["A27"] = 2;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B27"] = "Партнёры доверяют друг другу. Им одинаково хорошо и дома, и вне его. Любят природу, заботятся о близких, включая животных. Могут делиться друг с другом знаниями — эзотерическими и бытовыми, что укрепляет семейное благополучие. С уважением относятся к матерям друг друга, но не позволяют этому влиять на личную жизнь пары.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A28"] = 3;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B28"] = "В этой паре мужчина — добытчик, а женщина создаёт крепкий тыл и домашний очаг. Супруги уважительны друг к другу, окружают близких любовью и заботой — прекрасные родители и внимательные дети. В доме царит атмосфера уюта, всё процветает, включая растения. Обычно у такой пары несколько домашних питомцев.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A29"] = 4;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B29"] = "Мужчина в этой паре обеспечивает семью, а женщина создаёт уют и надёжный тыл. Оба относятся друг к другу с уважением, много заботятся о близких — хорошие родители и внимательные дети. Дом наполнен теплом, растения в нём хорошо приживаются. Нередко в семье появляется несколько питомцев.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A30"] = 5;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B30"] = "В отношениях этих людей — идиллия и полное взаимопонимание, про них можно сказать, что они нашли свою половинку. Пара серьёзно относится к семейным ценностям, чтит традиции, старается объединять семью под одной крышей не только по праздникам. В доме порядок и уют, хотя пара может жить довольно скромно. Много сил вкладывают в образование и развитие детей, поэтому дома собрана целая библиотека. Партнёры уважают планы друг друга и совместно распределяют время.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A31"] = 6;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B31"] = "Оба партнёра привлекательны и гармонично смотрятся вместе. Отношения тёплые, полные заботы и любви. Пара любит веселье — вечеринки, встречи с друзьями, активное общение. Но и в уединении чувствует себя комфортно — задушевные разговоры, завтрак в постель, романтические прогулки. Любят дарить подарки и устраивать сюрпризы без особого повода. Вместе ходят по магазинам, предпочитают красивые вещи. Знакомят друг друга с полезными людьми и дают ценные советы, как эффективнее выстраивать рабочее общение.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A32"] = 7;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B32"] = "У этой пары множество мечтаний, планов и целей. Активные люди, постоянно в движении, любят спорт. В выходные и отпуске выберут прогулку или поход, а не диван перед телевизором. Как минимум один из партнёров водит машину, они много ездят — по делам и в путешествия. Это союз двух карьеристов, поддерживающих успех друг друга. У пары есть потенциал развивать дело с нуля, открывая новые возможности.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A33"] = 8;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B33"] = "Эта пара встретилась не случайно — у партнёров есть общие задачи, которые предстоит решить вместе. С пониманием относятся к ошибкам друг друга, вместе проходят через трудности. Осуждению и унынию в этих отношениях нет места. Отлично организуют работу коллектива, дополняют друг друга в делах, что идёт на пользу любому совместному предприятию.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A34"] = 9;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B34"] = "Эту пару образуют две цельные, самостоятельные личности, нередко связанные с наукой. Комфортно рядом друг с другом, умеют молчать вместе, не вторгаются в личное пространство. Любят спокойное времяпрепровождение — книги, хорошие фильмы, тёплые встречи с близкими друзьями. У такой пары обычно немного детей.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A35"] = 10;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B35"] = "Судьба буквально помогает этой паре во всём. Это союз свободных, творческих людей, часто с гибким графиком и в творческой профессии. Не любят планировать, живут сегодняшним днём, доверяя собственным ощущениям, а не общепринятым нормам. Смотрят на жизнь с оптимизмом, открывают новые горизонты в любом деле, любят путешествия. К воспитанию детей относятся легко, выстраивая с ними дружеские отношения с раннего возраста.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A36"] = 11;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B36"] = "В этом союзе партнёры ежедневно прикладывают усилия ради общей цели. Оба энергичны, любят спорт и активный отдых, стараются ездить в отпуск несколько раз в год, свободное время проводят на природе. В семье обычно не меньше двух детей. Много времени проводят вместе, любят совместные игры и забавы, подходят к воспитанию мудро.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A37"] = 12;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B37"] = "Эта пара — люди «с добрым сердцем». Двери их дома открыты, они всегда рады помочь нуждающимся близким. Многое делают не для себя, а ради помощи другим — например, участвуют в благотворительности. Много работают, постоянно улучшая своё «гнездо», за жизнь не раз начинают своё дело с нуля и развивают его.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A38"] = 13;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B38"] = "Жизнь пары богата событиями и напоминает американские горки — безденежье сменяется достатком, успехи чередуются с неудачами. Любят путешествия и экстрим. Не захламляют жизнь старыми вещами. В этих отношениях рождаются новые идеи, которые партнёры без колебаний воплощают. Друзья, приходящие в гости, уходят с неожиданно смелым советом на насущный вопрос. В экстремальных ситуациях не теряются, готовы помочь при необходимости.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A39"] = 14;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B39"] = "Это красивые, чувственные отношения между двумя творческими людьми. Много времени уделяют разговорам об искусстве и поэзии, откровенны друг с другом. Любят отдых у воды — после него чувствуют себя обновлёнными и полными сил. Устраивают романтические вечера и поездки. Живут чувствами, не гонятся за материальным успехом и накоплениями. Могут вместе развиваться духовно и творчески, медитировать. В работе становятся идейными вдохновителями, оставляя исполнение профессионалам.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A40"] = 15;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B40"] = "Пара способна многого достичь вместе — не исключено, что самые смелые мечты этот союз воплотит в жизнь. Позволяют себе брендовые вещи, роскошные подарки, дорогие курорты. Отношения близкие и страстные — готовы исполнить любое желание друг друга. В доме царит атмосфера богатства и красоты. Партнёры принимают друг друга такими, какие есть, — полное взаимопонимание.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A41"] = 16;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B41"] = "Пара много времени и сил посвящает духовному развитию, вдохновляя на это других. Среди интересов — медитации, духовные течения, здоровое питание. Дисциплина и спорт поддерживают тело и дух в форме. Предпочитают необычный отдых — паломничества, посещение храмов, ретриты. Мечтают о собственном «месте силы» — доме, где можно собираться с единомышленниками для духовных практик, и упорно строят его, даже если стройка растягивается на годы.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A42"] = 17;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B42"] = "Союз двух ярких, творческих личностей с индивидуальным стилем. Любят наряжаться, подчёркивать статус одеждой. Популярны в своём кругу, способны получить широкое признание в деле, вплоть до настоящей известности. В какой-то момент их отношения становятся публичными, а окружающие начинают им подражать.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A43"] = 18;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B43"] = "Эта пара отличается доверительными, тёплыми отношениями, внимательна и сердечна друг к другу. Даже готовят с душой, вкладывая чувства в каждое блюдо. Сильно привязаны друг к другу — с первого прикосновения ясно, что им суждено быть вместе, а близость только укрепляет эту связь. Не могут порознь, стремятся проводить как можно больше времени вдвоём. Вдохновляют друг друга на общее дело, где раскрываются таланты обоих, поддерживают любые начинания. У пары немало целей и стремлений — постоянно развиваются вместе.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A44"] = 19;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B44"] = "Эта пара с улыбкой преодолевает трудности — в их жизни нет места ограничениям и негативу. Дела в руках этого союза часто получаются именно с третьей попытки, поэтому важно помнить: стоит пробовать снова. Партнёры увлекающиеся, интересуются новым, живут насыщенной событиями жизнью. Много сил и любви вкладывают в воспитание нескольких детей. Чаще предпочитают жизнь в доме с хозяйством, а не в квартире.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A45"] = 20;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B45"] = "Партнёры со значительной разницей в возрасте — это не мешает создать крепкую, нерушимую связь. Союз высоко ценит семейные традиции, часто собирает родных за одним столом без особого повода. Способны примирить давно не общающихся родственников. В профессии могут продолжить семейное дело или создать бизнес, который передадут наследникам.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A46"] = 21;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B46"] = "Эта пара любит путешествия и изучение языков, может кардинально менять место жительства, иметь жильё в разных городах или странах. Профессия часто связана с командировками и переездами. Партнёры поддерживают друг друга в любых обстоятельствах, а трудности только сплачивают их. Любят детей, возможна большая семья, но это не мешает другим интересам. У обоих чёткая позиция в вопросах веры, часто придерживаются определённой религии и её канонов. Этот союз объединяет людей с миротворческой позицией, против любого насилия и войн.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A47"] = 22;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B47"] = "Весёлая пара, любит развлечения и шутки в любом возрасте. Комфортно чувствуют себя без постоянного жилья — многолетняя привязанность к одному месту кажется им обременительной. Легки на подъём, любят путешествовать и планировать поездки. Хорошо проводят время с друзьями, у них много знакомых, но свой внутренний мир они не открывают посторонним. Не контролируют друг друга, дают свободу и независимость, помня о важности саморазвития. Способны на равных развить бизнес с нуля. Не любят ограничения и зависимости — и несут эту философию в мир.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A49"] = "3.Для финансового благополучия и счастливых отношений важно";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A50"] = 1;
SHEET_DATA_COMPAT["Данные совместимости"].literals["A51"] = 2;
SHEET_DATA_COMPAT["Данные совместимости"].literals["A52"] = 3;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B52"] = "Мужчине важно зарабатывать и обеспечивать семью, женщине — заботиться о муже и детях. Партнёрам важны взаимное уважение, забота о родителях, обустройство дома. Хорошо держать много животных и растений.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A53"] = 4;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B53"] = "Мужчине важно быть кормильцем семьи, а женщине — заботиться о муже и детях. Важны взаимное уважение, внимание к родителям, уют в доме. Хорошо, если в семье много питомцев и растений.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A54"] = 5;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B54"] = "Партнёрам важно договариваться друг с другом, вместе строить планы. Важно поддерживать порядок и уют дома, соблюдать традиции, собирать родных за одним столом.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A55"] = 6;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B55"] = "Паре важно заботиться друг о друге, разговаривать по душам, устраивать романтические вечера. Важны общение с друзьями, развлечения, подарки, красивая одежда для себя и друг друга. Партнёры хорошо умеют советовать, как выстраивать деловые связи и находить полезные знакомства.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A56"] = 7;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B56"] = "Хотя бы одному из партнёров важно водить машину. Хорошо много передвигаться, часто путешествовать, отдыхать активно. Важно ставить цели и помогать друг другу их достигать — возможен совместный бизнес.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A57"] = 8;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B57"] = "Партнёрам важно выполнять обещания, поддерживать друг друга, не осуждать, вместе преодолевать трудности. Пара умеет хорошо организовывать рабочий процесс, дополняя друг друга в делах.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A58"] = 9;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B58"] = "Партнёрам важно понимать и принимать друг друга, не вторгаясь в личное пространство. Умеют комфортно молчать вдвоём. Важно вместе читать, смотреть душевные фильмы. Хорошо, если в профессии есть место кропотливому труду и глубоким знаниям.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A59"] = 10;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B59"] = "Паре важно много путешествовать, радоваться жизни, генерировать идеи, открывать новые направления во всём. Важно работать в удовольствие, со свободным графиком, в творческой сфере.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A60"] = 11;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B60"] = "Партнёрам важны активность, лёгкость на подъём, спорт. Лучший отдых — на природе, с путешествиями несколько раз в год. Хорошо много гулять и веселиться с детьми. Важно вместе двигаться к общей мечте.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A61"] = 12;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B61"] = "Паре важно заниматься благотворительностью, помогать нуждающимся близким, делиться тем, что есть. Важны доброта и открытость к людям и друг к другу. Хорошо принимать гостей. Пара способна не раз в жизни начать своё дело с нуля и заметно улучшить условия жизни.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A62"] = 13;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B62"] = "Важно много путешествовать, впускать в жизнь экстрим и адреналин. Важно воплощать даже самые смелые идеи. Хорошо жить в просторном доме или квартире без хлама.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A63"] = 14;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B63"] = "Важно внимательно относиться друг к другу, проявлять чувства, заботиться, беседовать об искусстве. Хорошо вместе творить и медитировать. Лучший отдых — у воды. В работе важно быть вдохновителями проекта, а для его воплощения приглашать профессиональных исполнителей.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A64"] = 15;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B64"] = "Партнёрам важно понимать и принимать друг друга, поддерживать страсть в отношениях. Важно исполнять даже самые сокровенные желания друг друга, баловать дорогими подарками и особенным отдыхом. Вместе способны добиться всего — включая большие деньги и власть.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A65"] = 16;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B65"] = "Важно совместно расти духовно, медитировать, выбрать подходящую систему питания, соблюдать режим дня. Хорошо путешествовать к храмам и местам силы. Хорошо построить дом, где можно воплотить общий духовный проект.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A66"] = 17;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B66"] = "Паре важно быть на виду, яркими и интересными, стать примером для подражания. Важно следить, чтобы гардероб подчёркивал индивидуальность и творческую натуру. Важно выбрать сферу реализации, связанную с известностью.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A67"] = 18;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B67"] = "Партнёрам важны тактильный контакт, гармония в близости, больше совместного времени. Важно вдохновлять друг друга на новые начинания. Хорошо готовить с душой, вкладывая чувства. Совместно способны создать успешный бизнес.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A68"] = 19;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B68"] = "Паре важно легко относиться к трудностям. Хорошо иметь много увлечений и разнообразных интересов. Отлично, если пара живёт в своём доме и растит много детей. Важно легко подходить к бытовым вопросам — успех в любом деле особенно вероятен с третьей попытки.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A69"] = 20;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B69"] = "Паре важно собирать родных за одним столом, укреплять семейные узы, мирить поссорившихся родственников. Бизнес будет успешным, если его можно передать наследникам. Благоприятно продолжать семейное дело или ремесло.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A70"] = 21;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B70"] = "Партнёрам важно много путешествовать, изучать языки, иметь широкий круг интересов. Важно поддерживать друг друга в сложностях, не предъявлять претензий. Паре подходит недвижимость в разных городах и странах. Важны религиозная принадлежность и миротворческая позиция. Хорошо, если работа связана с частыми командировками.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A71"] = 22;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B71"] = "Партнёрам важно много путешествовать, вместе планировать поездки, чувствовать свободу. Хорошо сохранять лёгкое отношение к жизни и любовь к веселью. Паре не обязательно иметь своё жильё — гармонично можно жить и в съёмном. Важно оберегать личное пространство от посторонних. Совместный бизнес успешен при равноправном партнёрстве.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A73"] = "4.Проблемы и трудности";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A74"] = 1;
SHEET_DATA_COMPAT["Данные совместимости"].literals["A75"] = 2;
SHEET_DATA_COMPAT["Данные совместимости"].literals["A76"] = 3;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B76"] = "Мужчина терзается тем, что не может обеспечить достаток семье, не находит у жены поддержки, возможен риск алкоголизма. Женщине приходится работать за двоих, забывая о собственных потребностях. Отношения непростые — ссоры, скандалы, вспышки агрессии. Дети наблюдают такое поведение и перенимают его, обнажая семейные проблемы. Неуважение проявляется и друг к другу, и к родителям партнёра.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A77"] = 4;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B77"] = "Мужчина страдает от невозможности обеспечить семью, не получает одобрения и поддержки от жены, возможна склонность к алкоголю. Женщина вынуждена тянуть всё на себе, забывая о своих женских потребностях. В паре часты конфликты и агрессия. Дети видят это поведение и повторяют его, что делает семейные трудности заметными. Неуважение звучит как между супругами, так и по отношению к родителям второй половины.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A78"] = 5;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B78"] = "Партнёры не могут найти общий язык, постоянно опаздывают, мешают друг другу в делах. Порядок в доме либо полностью отсутствует у обоих, либо один поддерживает чистоту настолько скрупулёзно, что это раздражает второго. Пара не откровенна между собой, часто действует вопреки желаниям другого. Партнёры склонны читать нотации, указывать на недостатки, раздражаться на педантичность друг друга — есть риск развода.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A79"] = 6;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B79"] = "Отношения поверхностны, общение сводится к бытовым темам. Дефицит эмоциональной близости компенсируется дорогими подарками. Недостаток контакта восполняется общением с друзьями, возможны увлечения на стороне. Партнёры постоянно колеблются между постоянством и возможной интрижкой, между отношениями и работой. Со временем начинает раздражать внешний вид партнёра, звучат упрёки и замечания.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A80"] = 7;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B80"] = "Отношения в этой паре скорее рабочие, чем тёплые и семейные. Рождение детей постоянно откладывается ради карьеры. Партнёры требуют друг от друга полной самоотдачи, порой соревнуясь в достижениях. Возможны манипуляции ради влияния на цели партнёра. Один может пожертвовать своими амбициями ради второго, а затем постоянно напоминать об этом, провоцируя конфликты.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A81"] = 8;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B81"] = "Жизнь то и дело ставит пару в ситуации, где обнажаются несовершенства друг друга. Возникают разочарование и взаимная критика, партнёры видят друг в друге в основном недостатки. Проблемы не выносятся на публику, но за закрытыми дверями возможно даже домашнее насилие.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A82"] = 9;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B82"] = "В этой паре много секретов — партнёры умалчивают о трудностях, нуждах и даже проблемах со здоровьем. Каждый чувствует себя одиноким, не хватает взаимопонимания и поддержки. Страх быть покинутым заглушается общением на стороне и сомнительными связями. Недосказанность способна привести к алкоголю или другим зависимостям у одного из партнёров.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A83"] = 10;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B83"] = "Эта пара часто сталкивается с жизненными трудностями — тяжёлая работа с жёстким графиком за скромную плату без карьерных перспектив. Родственники нередко критикуют пару за несоответствие ожиданиям. Партнёры чувствуют, что живут не своей жизнью, и не уверены в общем будущем.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A84"] = 11;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B84"] = "Партнёры очень много работают, забывая об отдыхе, — не бывают на природе, не ездят в отпуск. В таких условиях друг друга начинают раздражать, не хватает сил на заботу о детях. Возникают ссоры и скандалы, вплоть до рукоприкладства. Между партнёрами нет взаимопонимания и взаимовыручки — присутствует желание использовать друг друга ради выгоды.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A85"] = 12;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B85"] = "Эти отношения держатся скорее на жалости и страхе причинить боль, чем на любви. Из-за этого же страха замалчиваются проблемы со здоровьем, пока они не станут серьёзными. Возникают сложности с совместными решениями — не удаётся найти компромисс. Нередко один из партнёров помогает кому-то другому в ущерб отношениям — например, забывает предупредить о задержке, пока второй ждёт на условленной встрече.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A86"] = 13;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B86"] = "Эти отношения нередко балансируют на грани разрыва. В паре кипят сильные страсти, нет уверенности в завтрашнем дне, эмоциональные всплески сложно контролировать. Присутствует необоснованный, тревожный страх за здоровье детей. Новый этап жизни часто начинается с утраты близкого человека и переосмысления пути. Паре тяжело даётся расставание и умение отпускать.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A87"] = 14;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B87"] = "Пара живёт в собственном выдуманном мире. Партнёры не до конца довольны выбором друг друга, есть сомнения и надежда встретить кого-то лучше. Отношения нельзя назвать идеальными — раздражение, отчуждение, накопленные обиды и переживания. Возникают сложности с финансами и бизнесом, ненужные траты, чрезмерное накопительство.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A88"] = 15;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B88"] = "Отношения строятся на взаимной выгоде, а не на любви. Дорогие покупки совершаются не по необходимости, а ради удовлетворения эго. Часты скандалы, ревность, взаимные обвинения — партнёры склонны видеть больше плохого, чем хорошего. Честность и верность не в числе их сильных сторон. Возможна агрессия вплоть до драк. Партнёры завидуют достоинствам друг друга, манипулируют ради личной выгоды, склонны к нездоровым увлечениям в интимной сфере.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A89"] = 16;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B89"] = "В этом союзе слишком приземлённый взгляд на жизнь — забота только о финансах. Возможны денежные трудности, потеря накоплений, долги и кредиты. Партнёры замыкаются друг от друга, часто выясняют отношения. Общих интересов почти не осталось, прежние чувства угасли, на их место пришло разочарование в любви. Возможны измены.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A90"] = 17;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B90"] = "Партнёрам сложно быть искренними друг с другом. Не хватает сердечности и душевности. Для окружающих создаётся образ «идеальной пары», но наедине всё иначе — скрываются истинные чувства, страхи, тревоги. Но всё тайное рано или поздно раскрывается, и союз столкнётся со своими проблемами. Недосказанность прорывается наружу — возможны обидные слова, хвастовство заслугами, стыд за партнёра.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A91"] = 18;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B91"] = "Пара боится буквально всего, особенно серьёзных решений — переезда, открытия своего дела. Сложно надолго расставаться и уезжать далеко — это ограничивает возможности каждого. Возможны душевные терзания, ревность, страх расставания. Еда, приготовленная без желания, скорее вредит союзу, чем помогает. Разница в интимном темпераменте тоже не идёт на пользу отношениям, а состояние здоровья одного из партнёров может мешать полноценной близости.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A92"] = 19;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B92"] = "Пара перестала ощущать вкус жизни. Попытки заработать не приносят результата, после каждой неудачи оба испытывают чувство вины. Ещё до начала дела возникает страх провала. В таких условиях сложно чувствовать благодарность за имеющееся и радоваться настоящему моменту. Ради угождения партнёру возможно излишнее вторжение в личное пространство друг друга.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A93"] = 20;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B93"] = "Отношения скорее дружеские, без сильного влечения и романтики. Возможны разногласия по поводу отношений с родственниками, отсюда ссоры и недопонимание. Партнёры могут переносить друг на друга нерешённые проблемы в отношениях со своими родителями. Пара боится что-либо менять в жизни, опасаясь потерять уже имеющееся, — не решается открыть своё дело, живёт без определённости. Родственников может не устраивать этот союз, и они пытаются разрушительно влиять советами.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A94"] = 21;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B94"] = "Партнёры не принимают друг друга такими, какие есть, пытаются переделать. Возможны либо копирование родительской модели отношений, либо, наоборот, старательное избегание родительских ошибок. Нет финансовой стабильности — жизнь в долг и кредитах. Нет чёткой духовной позиции, нежелание быть причастными к какой-либо религии. Периодически болеют всей семьёй — но хорошо разбираются в докторах и лекарствах.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A95"] = 22;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B95"] = "В этом союзе один из партнёров зависим от другого — в деньгах, работе или даже здоровье. Пара с трудом путешествует, постоянно натыкаясь на препятствия. Партнёры не чувствуют себя свободными, боятся новых возможностей, круг общения ограничен. Возможны отношения, где один или оба партнёра уже состоят в другом браке. Есть риск тюремного заключения одного из пары.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A97"] = "5.Если пара не выполняет то, для чего встретилась включается негативная карма";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A98"] = 1;
SHEET_DATA_COMPAT["Данные совместимости"].literals["A99"] = 2;
SHEET_DATA_COMPAT["Данные совместимости"].literals["A100"] = 3;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B100"] = "Мужчина не может обеспечить семью, возможен алкоголизм. Женщина берёт на себя мужские обязанности. Неуважение к партнёру и его родителям. Скандалы. Агрессия.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A101"] = 4;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B101"] = "Мужчина не справляется с ролью кормильца, возможна склонность к спиртному. Женщина вынуждена брать на себя мужские функции. Отсутствие уважения к партнёру и его родным. Конфликты, вспышки агрессии.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A102"] = 5;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B102"] = "Партнёры не могут договориться о взаимодействии, закрываются друг от друга, не получается душевных разговоров. В доме нет уюта, царит беспорядок. Есть риск расставания.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A103"] = 6;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B103"] = "Отношения становятся поверхностными, ограничиваются дежурными фразами и бытом. Партнёры откупаются дорогими подарками. Дефицит общения компенсируют встречами с друзьями. Возможны измены.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A104"] = 7;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B104"] = "Рождение детей постоянно откладывается. Отношения становятся излишне деловыми, партнёры соревнуются в достижениях, требуют друг от друга исполнения задач как от подчинённых. Возможна жертва своими интересами ради другого с последующими упрёками.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A105"] = 8;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B105"] = "Возможны физическая агрессия, разочарование в партнёре, споры, обиды, подавленное состояние. Партнёры видят друг в друге только недостатки.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A106"] = 9;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B106"] = "Пара скрывает друг от друга истинные потребности и проблемы, нет взаимопонимания. Оба одиноки, даже находясь в отношениях. Возможна склонность одного из партнёров к зависимостям.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A107"] = 10;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B107"] = "У пары трудная судьба, тяжёлая работа без достойной оплаты. Партнёры живут не своей жизнью, но всё равно подвергаются критике родных, не видят совместного будущего.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A108"] = 11;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B108"] = "В паре не принимают друг друга, возникают скандалы и агрессия. Партнёры пытаются влиять на решения друг друга, манипулируют. Оба — трудоголики, не умеющие отдыхать.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A109"] = 12;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B109"] = "Отношения держатся на жалости и страхе обидеть друг друга. Сложно даются совместные решения. Партнёры скрывают проблемы со здоровьем, откладывая до критического момента.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A110"] = 13;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B110"] = "В жизни пары нет определённости, отношения полны страстей. Во время ссор партнёры теряют контроль, возможны физическая агрессия и жестокость. Решив расстаться, не могут отпустить друг друга.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A111"] = 14;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B111"] = "Партнёры обижаются друг на друга, испытывают недовольство и переживания. Сложно даются финансовые решения, много ненужных трат. Возможны мысли о более подходящем партнёре.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A112"] = 15;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B112"] = "Партнёры скандалят, обвиняют друг друга, манипулируют, видят только негатив. Гнев способен перерасти в рукоприкладство. Пара остаётся вместе лишь из финансовой выгоды. Возможны измены и нездоровые интимные пристрастия.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A113"] = 16;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B113"] = "Нет духовного роста, жизнь в долгах и кредитах, риск потерять всё заработанное. Нет общих интересов и тем для разговора — только ссоры. Партнёры закрываются друг от друга. Возможны измены.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A114"] = 17;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B114"] = "Отношениям не хватает душевного тепла, истинные переживания скрываются. На публике пара играет роль «идеальной», но всё иначе внутри. Со временем тайны раскрываются, и партнёры начинают упрекать друг друга накопленным негативом, одному становится стыдно за другого.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A115"] = 18;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B115"] = "Партнёры боятся принимать важные решения, ревнуют, боятся отпускать друг друга далеко. Возможны интимные сложности из-за разницы темпераментов.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A116"] = 19;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B116"] = "Пара перестала радоваться жизни, не умеет наслаждаться настоящим. Каждый винит себя в неудачах. Попытки заработать безрезультатны, жизнь в безденежье. Партнёры чрезмерно контролируют друг друга.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A117"] = 20;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B117"] = "Скандалы часто связаны с отношениями с родственниками, которые вмешиваются и пытаются разрушить союз. Страх перемен, боязнь открыть своё дело, неуверенность в будущем. Партнёры переносят друг на друга проблемы в отношениях со своими родителями.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A118"] = 21;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B118"] = "Партнёры навязывают друг другу своё видение жизни, не принимая таким, какой есть. Жизнь обременена долгами и финансовыми проблемами. Периодически болеет вся семья. Нет тяги ни к одной религии, отсутствует духовное развитие.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A119"] = 22;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B119"] = "Один партнёр зависим от другого — финансово или по здоровью, не чувствует свободы. Круг общения ограничен, путешествия недоступны. Страшно начинать что-то новое. Возможно тюремное заключение одного из пары.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A121"] = "6.Зона комфорта в отношениях";
SHEET_DATA_COMPAT["Данные совместимости"].literals["B121"] = "Центральная энергия в матрице определяет как партнеры взаимодействуют друг с другом. Это общая зона комфорта для пары. Для того, чтобы вместе было хорошо необходимо пройти урок этой энергии. Также эта точка расскажет о том к чему паре следует стремиться в отношениях, чтобы оба партнера были счастливы, а в паре царила гармония.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A122"] = 1;
SHEET_DATA_COMPAT["Данные совместимости"].literals["A123"] = 2;
SHEET_DATA_COMPAT["Данные совместимости"].literals["A124"] = 3;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B124"] = "Зона комфорта пары — стабильный, крепкий союз, где главные решения принимает женщина, но важно, чтобы она учитывала и уважала мнение партнёра. Важно не поддаваться общественному мнению и не воспринимать советы родственников как истину в последней инстанции. Для гармонии важно слушать друг друга и быть взаимной опорой. Смысл в отношения добавляют дети и уютный, налаженный быт. Важно вместе учиться зарабатывать, создавать блага и щедро делиться ими с другими, стать обеспеченной парой, но не наделять деньги сверхценностью и не привязываться к материальному.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A125"] = 4;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B125"] = "Зона комфорта — совместная постановка материальных целей. В этих отношениях сильные эмоции способны преобладать над рассудком. Важно не ограничивать личное пространство друг друга и не поддаваться разрушительным чувствам. Комфорт задаёт мужчина, но важна лидерская позиция обоих партнёров, принятая как данность, — оба по-своему сильные личности. Важно строить и приумножать всё вместе, с самого фундамента — отношения, семью, дом.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A126"] = 5;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B126"] = "В этих отношениях партнёрам важно ценить и уважать друг друга, помогать друг другу ориентироваться в потоке жизни, не давая запутаться во взглядах. Важно не заострять внимание на разнице характеров, взглядов и социального положения. Обмен информацией, изучение нового, дискуссии пойдут на пользу отношениям. Важно отказаться от идеи поучать друг друга или опираться на устаревшие обычаи.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A127"] = 6;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B127"] = "Зона комфорта этой пары — открытость чувств и взаимная поддержка. Чем дольше партнёры вместе, тем сильнее любовь. Обоим важно научиться ценить красоту и гармонию. Умение любить себя помогает дарить любовь и партнёру. Борьба за лидерство приводит к обидам и портит отношения. Важно научиться безусловному принятию друг друга, избегая эмоциональных качелей от любви до ненависти.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A128"] = 7;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B128"] = "Эта пара создана для ярких, динамичных отношений, наполненных путешествиями и новыми знакомствами. Важно стремиться к общим целям, не бояться переездов. Совместное время и обоюдное желание расти как личности объединяет пару. Если один из партнёров часто в командировках, второму важно относиться к этому с пониманием. Искренняя радость за достижения партнёра укрепляет союз.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A129"] = 8;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B129"] = "Паре комфортен официальный брак на взаимовыгодных условиях. Не стоит пытаться изменить партнёра — лучше обратить внимание на себя. Всё, что каждый дарит второй половине, возвращается приумноженным — будь то понимание или, наоборот, агрессия. Этот процесс бесконечен, пока один из партнёров не возьмёт ответственность на себя и не начнёт меняться сам, а не ждать перемен от другого.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A130"] = 9;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B130"] = "Пара умеет ценить личное пространство друг друга, уважает желание уединиться за любимым занятием. При этом важно помнить: душевные разговоры укрепляют союз. Откровенные беседы о желаниях и чувствах важны, иначе есть риск замкнуться в себе. Важно заботиться не только о духовном развитии, но и радовать себя материальными благами. Паре под силу совместный проект, несущий знания людям.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A131"] = 10;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B131"] = "Этой паре важно вместе мечтать об успехе и приумножать благосостояние совместными усилиями. Важно найти ответ на вопрос: «Что нам нравится делать вместе?». При общих интересах, проекте, времяпрепровождении, хобби и друзьях эти отношения способны стать союзом на всю жизнь. Лучшее, что можно сделать для отношений, — получать удовольствие от жизни и находить радость во всём. Тогда паре будет сопутствовать успех — главное не мешать удаче и пользоваться счастливыми совпадениями.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A132"] = 11;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B132"] = "Крепкие, здоровые отношения без борьбы за власть обеспечены паре при совместной физической активности, яркой близости и здоровом образе жизни. Многое будет даваться легко, если стремиться к целям через раскрытие потенциала, а не тяжёлый труд. В этой паре лидерство лучше отдать мужчине, а роль женщины — вдохновлять, верить и поддерживать. Не стоит торопить партнёра или злиться на его темп — важно давать друг другу время. Комфорт обеспечен, если оба проявляют силу характера и поддерживают друг друга.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A133"] = 12;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B133"] = "Отношения этой пары могли начаться необычно. Чтобы их сохранить, вероятно, придётся отказаться от чего-то важного, обрести внутреннюю опору и уверенность, не впадая в зависимость от партнёра. Движущая сила отношений — желание быть полезными друг другу и миру. Ни один из партнёров не должен жертвовать своими интересами ради другого. Важно полюбить себя и заниматься любимым делом. Помощь партнёру должна идти не из жалости или чувства долга, а от внутренней наполненности и благодарности. Совместное творчество и креатив укрепляют союз.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A134"] = 13;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B134"] = "Эти отношения могут быть чрезмерно эмоциональными. Для комфорта важно легко относиться к переменам, менять привычки, принимать, что партнёр развивается и меняется. Не стоит бояться выходить на новый уровень отношений. Рутина губительна для этой пары — важно постоянно искать новое, не увязая в быту. Не стоит цепляться за отжившее — отпустив его, освобождаешь место для нового. Хорошо вместе изучать философию жизни и смерти, законы мироздания, не бояться вынужденных перемен и видеть в кризисах новые возможности. Важно поддерживать друг друга в смелых решениях — оправданный риск идёт этим отношениям на пользу.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A135"] = 14;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B135"] = "Для комфорта партнёрам важно учиться находить компромиссы. Общие цели объединяют пару. Нельзя зацикливаться только на материальном благополучии. В целом партнёрам уютно вместе. Союз будет долгим и счастливым, если оба интересуются искусством и творчеством, вместе наслаждаются красотой мира. Важно стремиться к искренним, тёплым, открытым отношениям — в этом помогут общие точки соприкосновения и творческие интересы. Стоит быть осторожнее с любыми излишествами — в еде, алкоголе, эмоциях, — бережно относясь к здоровью друг друга.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A136"] = 15;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B136"] = "В этой паре каждый партнёр самодостаточен. Союз усиливает эмоционально-интимная связь. Важно научиться справляться с негативными эмоциями экологично, без вреда для здоровья. Одна из главных задач — принять и понять теневые стороны друг друга. Важна и материальная сторона — оба заинтересованы в деньгах, важно работать над достатком сообща. Стоит учиться прощать, избегать постоянной критики и претензий, оставаться верными друг другу, заниматься саморазвитием и духовным ростом.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A137"] = 16;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B137"] = "Про такую пару говорят «с перчинкой». Комфорт возможен, если партнёры научатся вовремя сглаживать любые трещины в отношениях, — иначе частые ссоры измотают морально и физически, вплоть до расставания. Для взаимопонимания полезно совместное занятие, трансформирующее не только материальную, но и духовную сторону, — изучение основ мироздания, йога, цигун, танцы. Возможен совместный проект по саморазвитию. Строительство дома, переезды и ремонты укрепляют союз.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A138"] = 17;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B138"] = "Партнёрам важно помогать друг другу находить свой путь и вместе познавать красоту мира. Это яркий союз с высоким творческим потенциалом. Задача — поддерживать таланты друг друга, доводя их до профессионального уровня. Важно ценить партнёра — тогда пара сможет прожить долгую и счастливую жизнь. При выборе жилья лучше отдавать предпочтение экологически чистым районам. Паре важно поддерживать чистоту и порядок вокруг себя.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A139"] = 18;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B139"] = "Партнёрам полезно вместе заниматься творчеством, энергетическими практиками, психологией. Важны честность и открытость, без тайн и секретов — всё тайное рано или поздно раскрывается и способно навредить отношениям. Важно уметь говорить друг с другом открыто на любую тему. Принципиальные вопросы лучше решить в начале отношений, чтобы избежать иллюзий и разочарования, когда партнёр перестанет соответствовать «идеальному» образу. Союз укрепляет совместная борьба со страхами и фобиями.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A140"] = 19;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B140"] = "Для гармонии партнёрам важно вместе стремиться к изобилию и процветанию. У пары большая миссия — светить другим, заниматься общественной работой и благотворительностью, заботиться об окружающих. Главное — не душить окружающих чрезмерной заботой, распределяя усилия между разными проектами, а не зацикливаясь на одном. Нельзя замыкаться друг на друге, ведя затворнический образ жизни, — есть риск «испепелить» друг друга избыточным вниманием. Ещё одна важная задача — рождение или усыновление детей. Паре под силу масштабный проект, который принесёт финансовое благополучие и поможет другим стать успешнее.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A141"] = 20;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B141"] = "Пару объединяет схожий взгляд на семью и традиционные ценности. Важно ценить свой род и помогать близким. Собственная семья во многом строится по образу отношений с родителями — у мужчины на брак влияют отношения с матерью, у женщины отношения с партнёром формируются под влиянием связи с отцом. Хорошо, если пара решится на своё дело, которое можно будет передать наследникам.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A142"] = 21;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B142"] = "Прекрасная энергетическая совместимость, возможны отношения на всю жизнь. Хорошо, если пара часто меняет место жительства или много путешествует. Для дома лучше выбирать просторные помещения с большими окнами. Гармония возможна, если оба открыты новому, осознанно отказываются от ограничивающих установок и помогают друг другу расширять сознание. Важно верить друг в друга и вдохновлять — тогда по плечу даже самые смелые планы. Стоит следить за словами о мире и людях — избегать негативных оценок, иначе это может обернуться агрессией со стороны окружающих, направленной на пару.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A143"] = 22;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B143"] = "Зона комфорта пары — лёгкость в отношениях друг с другом. Важно отказаться от ревности и всего, что сковывает союз. Одна из главных задач — научиться отвечать за собственные решения, позволяя партнёру нести ответственность за свои. Важно жить настоящим моментом, ценить и любить то, что уже есть. Не стоит ограничивать друг друга — это не пойдёт на пользу отношениям. Важно проработать страхи, связанные с рождением детей, — в этом союзе дети принесут огромное счастье.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A145"] = "7.Рекомендации для пары";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A146"] = 1;
SHEET_DATA_COMPAT["Данные совместимости"].literals["A147"] = 2;
SHEET_DATA_COMPAT["Данные совместимости"].literals["A148"] = 3;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B148"] = "Отношения в такой паре нужны, чтобы каждый учился созидать, развивал ответственность и хозяйственность, заботился о близких. Важно не только вести быт, но и заниматься самореализацией и творчеством. Не стоит избегать ответственности. Совместные домашние обязанности, уют, наслаждение материальными и чувственными радостями, рождение и воспитание детей сплачивают пару. Важно правильно распределять традиционно мужскую и женскую роли, передавать эти навыки детям. Быть примером домовитости и гармоничной семьи.\nРекомендации для гармоничного развития отношений:\nВзяв на себя ответственность, не стоит стремиться к тотальному контролю. Распределите обязанности заранее и не нервничайте из-за отклонений от плана — лучше обсудить зоны ответственности «на берегу», чтобы избежать скандалов.\nПроявляйте рачительность в хозяйстве, заботьтесь об уюте — не только ради удобства, но и ради красоты пространства. Если не хватает времени — привлекайте помощников или пользуйтесь готовыми услугами.\nБудьте гостеприимны и мудры. Уделяйте время духовному развитию, не тратя все силы только на материальное.\nЗанимайтесь воспитанием детей, передавайте традиционные ценности — девочек учите манерам и рукоделию, мальчиков — ремеслу и ответственности за близких.\nВоспитывайте в себе оптимизм, радуйте других от души, но не забывайте баловать и себя простыми земными радостями.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A149"] = 4;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B149"] = "Пару объединяет общий взгляд на карьеру, работу, планирование и организацию. Возможен совместный успешный бизнес, активная деятельность. Важно балансировать личную жизнь и работу, находить общий язык в любой ситуации, договариваться на условиях, устраивающих обоих. Важны мудрость, любовь, терпение, а не демонстрация власти и подавление. Организаторские способности стоит применять в работе — создавать бизнес или строить карьеру, не бояться ответственности и лидерства.\nРекомендации для гармоничного развития отношений:\nОпределитесь заранее с приоритетами и взглядами на жизнь — обсудите роли и зоны ответственности в доме и на работе (если она общая). Объясните партнёру, что допустимо в вашей системе ценностей.\nПриняв на себя обязательства — придерживайтесь их. Не уклоняйтесь от ответственности и не манипулируйте партнёром — просите, а не требуйте, мотивируйте, а не диктуйте.\nПоддерживайте баланс семейного бюджета, заботьтесь о доме и совместном имуществе — при нехватке сил пользуйтесь услугами специалистов.\nРаспределите роли — кто отвечает за стратегические решения, кто поддерживает.\nВажно поддерживать отношения, не жертвуя семьёй ради карьеры. При этом совместный бизнес у таких партнёров может быть успешным — если строго разделять рабочее и личное пространство.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A150"] = 5;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B150"] = "Партнёры в этом союзе учатся уважению и полному принятию друг друга со всеми чертами и ценностями. Важно делать акцент на позитивном, ценить и гордиться близким человеком. Разделять цели и достижения партнёра, вместе учиться и расширять кругозор. В творческом тандеме важно разглядеть потенциал друг друга и помогать его раскрывать. Совместное обучение и общая система ценностей сближают ещё сильнее. Достигнув определённого уровня, партнёры могут стать наставниками для окружающих — их авторитет строится на достижениях, глубине знаний и стремлении к справедливости.\nРекомендации для гармоничного развития отношений:\nЖенщине стоит проработать отношения с мужчинами, включая недопонимания с отцом, — научиться уважать мужчин, не беря на себя их роль.\nМужчине важно не избегать ответственности, а выводить отношения на новый уровень, действуя не только в своих интересах, но и в интересах партнёрши.\nВ такой паре нередок мезальянс по возрасту, статусу или культуре — преодолеть барьеры помогут личностный рост, обсуждение религии и политики без цели что-то доказать, а ради взаимного обогащения.\nХорошо учиться вместе — языкам, профессиональным навыкам.\nСовместный путь может быть связан с поиском предназначения — найдя его, партнёры обретают настоящую гармонию.\nПо возможности стоит выстроить традиционную модель отношений с ответственностью мужчины во главе, поддерживать семейные традиции, изучать историю семьи.\nЕсли традиционная модель не подходит — важно взаимодействовать на равных, развиваясь и в материальном, и в духовном плане.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A151"] = 6;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B151"] = "В паре важно чувствовать друг друга и прислушиваться к партнёру — подсказки судьбы часто приходят именно через него. Сложные вопросы важно решать вместе — тогда шанс на удачный выбор выше. Сомнения одного способны всё испортить, поэтому важны сотрудничество, поддержка и принятие. Важно оставаться открытыми, искренними, стремиться не к показной, а к настоящей гармонии в отношениях. Уделять внимание близким, детям, создавать красоту в доме, развивать тонкий вкус — в кулинарии, интерьере, повседневных мелочах.\nРекомендации для гармоничного развития отношений:\nНаучитесь по-настоящему любить, открываться и доверять партнёру, не бояться близости, хранить верность.\nСтройте прочные отношения не напоказ — опекайте близких, стремитесь к полноценной семье.\nУделяйте время быту и обустройству дома — не только ради удобства, но и красоты.\nРазвивайте вкус — посещайте выставки, занимайтесь дизайном, следите за собой не только по особым случаям.\nИзбегайте отстранённости, чаще проявляйте нежность — телесный контакт очень важен для пары.\nСоздавайте полезные связи, не избегайте новых знакомств, привлекайте внимание не только манерами, но и глубиной разговора.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A152"] = 7;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B152"] = "Партнёрам важно проявлять активность и динамику, двигаться в одном направлении, быть готовыми к быстрому развитию отношений. Важны стратегия и контроль — как над внешними событиями, так и над собственными эмоциями. Не стоит торопить ни себя, ни партнёра — важно давать событиям идти естественным ходом, но и не затягивать решения. Если один партнёр решительнее — он может научить этому другого, а второй, в свою очередь, поможет гармонизировать излишнюю вспыльчивость первого.\nРекомендации для гармоничного развития отношений:\nИспользуйте разные виды совместной активности — обустройство дома, спорт, активный отдых.\nПо возможности путешествуйте — именно в поездках проще принимать решения, если что-то застопорилось.\nПолезно учиться новому и применять знания на практике, делясь ими с другими.\nНе рискуйте чрезмерно ради адреналина — выбирайте продуктивную деятельность или экстрим со страховкой.\nИзбегайте спонтанных решений и вспышек гнева — обдумывайте цели вместе, регулярно работайте над задуманным.\nСоревновательность лучше направить в здоровое русло — совместный бизнес или спортивные состязания.\nПри сложностях обращайтесь к специалистам — коучинг поможет выстроить стратегию успеха.\nНе только теоретизируйте, но и применяйте знания на практике.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A153"] = 8;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B153"] = "Партнёры учатся бережно относиться к себе и друг другу, без претензий и обид, с полным принятием. Предстоит много решать и договариваться, взвешенно принимать решения, не беря на себя роль судьи для другого. Терпимость и умение прощать сделают отношения счастливее. Стоит опираться на дар примирять и сглаживать конфликты, доверять судьбе и течению событий. Изучение вселенских законов и причинно-следственных связей поможет примириться с тем, что кажется несправедливым.\nРекомендации для гармоничного развития отношений:\nБольше разговаривайте, решайте вопросы разумными компромиссами, без лишних эмоций.\nИзбегайте категоричности и навешивания ярлыков, но помогайте более слабым отстаивать права.\nИзбавляйтесь от негативных установок, стремитесь к мирному урегулированию споров.\nУважайте общественные правила, но вырабатывайте и собственные договорённости, комфортные именно для вас.\nПринимайте жизнь без жалоб, воспринимая происходящее как уроки. Изучайте законы Вселенной, разговаривайте дипломатично.\nПроявляйте больше нежности и искренности, учитесь прощать и вставать на чужую позицию.\nНе берите на себя чужую ответственность, уважайте право других жить по-своему.\nЗдоровые личные границы защитят от недопонимания и манипуляций.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A154"] = 9;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B154"] = "Отношения зависят от того, насколько быстро партнёры научатся балансу и золотой середине во всём. Важно избегать крайностей — от замкнутости и желания отшельничества до чрезмерной привязанности к партнёру или материальному. Возможно ощущение одиночества в паре из-за стремления к полному слиянию с партнёром. Важно набираться мудрости, развиваться духовно, черпать знания из разных источников — это расширяет кругозор и меняет взгляд на мир. Полезно расширять круг общения, делиться знаниями. Возможен интерес к эзотерике и нетрадиционным знаниям — не стоит его бояться, лучше развивать.\nРекомендации для гармоничного развития отношений:\nКаждому важно стать самодостаточной личностью, не зависящей от партнёра, уважая при этом его личное пространство.\nПрочувствуйте настоящую свободу без необходимости уединения — не ограничивайте себя и друг друга в новом опыте.\nОбщий интерес к науке или истории поможет сблизиться — поддерживайте стремление партнёра к знаниям, обсуждайте глобальные, философские темы.\nГармонизации поможет природа — выезды на природу, места силы.\nВыработайте здоровое отношение к деньгам — не делая их самоцелью, но и не пренебрегая финансовой стороной. Обсуждайте денежные вопросы открыто.\nЗанимайтесь благотворительностью, избегайте жадности, радуйте друг друга нематериальными подарками — книгами, знаниями, путешествиями.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A155"] = 10;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B155"] = "Такие отношения учат материальной независимости и разумным тратам по потребностям — своим и партнёра. Партнёры смогут стать обеспеченными, если будут видеть и использовать возможности вокруг, доверять интуиции, оказываться в нужном месте в нужное время. Оба ярко проявляют себя в обществе, окружающие считают такую пару удачливой — и не без оснований: при позитивном развитии деньги буквально идут в руки. Важно выработать здоровое отношение к финансам — воспринимать их как возможности, разумно распоряжаться, не впадая ни в мотовство, ни в жадность. Важна и благотворительность.\nРекомендации для гармоничного развития отношений:\nБудьте в центре событий, ведите активную жизнь, расширяйте круг полезных знакомств.\nПрактикуйте позитивное мышление, доверяйте себе и партнёру. Используйте удачу честно, щедро делитесь успехом с теми, кто помог его достичь.\nУправление эмоциями и чёткая стратегия убережёт от соблазнов и рискованных авантюр.\nИзвлекайте опыт из каждой ситуации, избегая повторения ошибок.\nФинансовая грамотность и мышление успешного человека ускорят достижение целей — как и умение прислушиваться к внутреннему денежному чутью.\nПолезен совместный бюджет — стремитесь к большему, но благодарите за уже достигнутое.\nДля активизации удачи полезны спонтанные поездки и участие в разных активностях — учитывая интересы обоих.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A156"] = 11;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B156"] = "Отношения даны для развития физических данных и силы воли партнёров — важно научиться правильно применять эти способности. Использовать потенциал в спорте, активной работе, управлении без давления и агрессии. Избыток энергии стоит направлять в продуктивное русло. Партнёры учатся слушать друг друга и разрешать разногласия. Хорошо, если есть общие хобби, связанные со спортом, танцами, здоровым образом жизни, — важно помогать друг другу раскрывать потенциал в этом направлении.\nРекомендации для гармоничного развития отношений:\nНаправляйте энергию союза не на конкуренцию друг с другом, а на развитие — можно обучать и наставлять других в спорте.\nУчитесь управлять эмоциями и физической силой, избегайте решения вопросов силой.\nРаскрывайте сексуальность друг друга, доверяйте партнёру, заботьтесь о теле вместе.\nПоддерживайте здоровый образ жизни — спорт, фитнес, танцы, массаж, спа, энергетические практики.\nСнять напряжение помогут экстремальный спорт, стрельба, бокс.\nРазвивайте не только тело, но и дух — не избегайте глубоких философских тем.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A157"] = 12;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B157"] = "Отношения даны для важного духовного опыта и глубоких трансформаций. Обоим важно научиться тонко чувствовать и сопереживать, при этом разграничивая свои эмоции и чужие, не растворяясь полностью в партнёре. Важно избегать жертвенности и жизни в иллюзиях. Трезвый взгляд на себя и мир поможет выстроить зрелые, гармоничные отношения. Важно установить здоровые личные границы, избегать манипуляторов и токсичных людей, оказывать разумную поддержку — «давать удочку, а не рыбу».\nРекомендации для гармоничного развития отношений:\nОсвобождайтесь от иллюзий и зависимостей, развивайте самостоятельность, не питайте завышенных ожиданий от партнёра.\nИзбавляйтесь от манипуляций — не позволяйте себя обесценивать и не поддавайтесь чужим уловкам.\nПолезны любые контакты с водой — бассейн, отдых у воды, дайвинг, даже аквариум дома.\nМедитация, йога, путешествия к местам силы помогут сбалансировать внутреннее состояние.\nДоверяйте друг другу полностью, не бойтесь открывать даже самые «странные» стороны.\nЗанимайтесь вместе благотворительностью, развивайте эмпатию, не отгораживайтесь от чужих проблем.\nПри сложностях в паре полезна работа с психологом.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A158"] = 13;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B158"] = "Партнёрам важно быть прогрессивными, постоянно меняться и освобождаться от старого, мешающего развитию. Смело отбрасывать ограничивающие установки, расхламляться на бытовом уровне — и в себе, и вокруг. Так через кризисы и потери удастся преодолеть страхи и выйти на новый уровень. При этом важны мудрость и предусмотрительность — тщательно выбирать, от чего отказаться, а что сохранить, избегая напрасного риска.\nРекомендации для гармоничного развития отношений:\nПринимайте перемены, не останавливайтесь в развитии — расчищайте пространство дома, на работе и в душе.\nБережно относитесь друг к другу — к эмоциям, чувствам, здоровью. Не рискуйте понапрасну, действуйте обдуманно.\nТягу к адреналину реализуйте экологично — экстремальный спорт со страховкой, путешествия.\nПрорабатывайте эмоциональный фон, учитесь жить «здесь и сейчас».\nСовместные трансформации — как телесные (закаливание, похудение), так и духовные (личностный рост) — укрепляют пару.\nПоддерживайте друг друга, если перемены пугают, — обсуждайте страхи открыто.\nРазвивайте тактильность — массаж, объятия.\nПериодически расхламляйтесь — расставайтесь с устаревшим (вещи, отношения, обязательства) и впускайте новый опыт.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A159"] = 14;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B159"] = "Партнёрам важны баланс и гармония во всём — умение сохранять внутреннее равновесие не только в отношениях, но и в жизни. Важно ценить то, что есть, а не то, чего не хватает, самостоятельно закрывая свои потребности — плохо, когда один или оба постоянно нуждаются в партнёре как в источнике заботы. Важно самим вносить в отношения романтику и яркость, не позволяя им превратиться в рутину, — через креативность и новые впечатления.\nРекомендации для гармоничного развития отношений:\nСоблюдайте меру во всём, избегайте жадности и стремления «присвоить» партнёра.\nНе нарушайте личных границ — у каждого должно быть своё пространство, интересы, друзья, наряду с общими ценностями.\nПридавайте союзу динамику — проявляйтесь активно сами, не ждите инициативы от другого.\nНе позволяйте быту превратить жизнь в рутину — регулярно вносите позитивные эмоции.\nПрактикуйте доверие миру и друг другу, радуйтесь тому, что есть.\nСовместное увлечение искусством укрепит баланс — выставки, театр, авторское кино.\nПолезно просто помолчать вместе — у реки, у камина.\nПарная фотосессия поможет лучше почувствовать друг друга.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A160"] = 15;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B160"] = "Позитивный сценарий отношений зависит от умения не впадать в зависимость друг от друга (в том числе финансовую) и отказаться от негативных привычек, обуздать эмоции и страсти. Партнёрам предстоит раскрыть друг другу свои теневые стороны, вместе избавляться от ревности, жадности, лжи, опыта созависимых отношений. Важно не воздействовать друг на друга нечестными способами, включая магические практики, и как можно скорее избавиться от негативного влияния, если оно есть. При наличии тяжёлых зависимостей у одного из партнёров важно вместе искать выход, а не отстраняться.\nРекомендации для гармоничного развития отношений:\nПрорабатывайте негативные эмоции экологично, превращайте недостатки в достоинства — например, жадность в щедрость через благотворительность.\nВыходите из токсичных отношений в окружении и на работе, не позволяйте манипулировать собой.\nОчищайте жизнь от зависимостей, не поддавайтесь страстям.\nИзбегайте чрезмерной привязанности — энергетической, финансовой, сексуальной, — развивайте психологически здоровые отношения.\nНе занимайтесь тёмной магией, тщательно выбирайте окружение.\nОткрывайтесь друг другу без страха быть высмеянными, раскрывайте вместе свою сексуальность.\nОбсуждайте деньги открыто, не делая их культом, — изучайте финансовую грамотность.\nПомогайте окружающим осознавать и прорабатывать собственные слабости.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A161"] = 16;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B161"] = "Партнёры учатся направлять в конструктивное русло мощную энергию союза — без осознанности она способна разрушать всё вокруг. Отказ от старого и разрушение в этих отношениях имеют смысл, только если освобождают место для нового и продуктивного. Строительство и реконструкция возможны во всех смыслах — от реальных зданий и бизнеса до изменения мировоззрения. Самоконтроль и ясность ума помогают принимать взвешенные решения, избегая импульсивных срывов.\nРекомендации для гармоничного развития отношений:\nУчитесь сохранять внутренний баланс, работайте над собой вместе, стройте что-то важное и светлое.\nУчитесь вовремя поддерживать друг друга.\nНе стремитесь контролировать друг друга и других, не вмешивайтесь в чужую жизнь.\nСтройте, создавайте своими руками, реставрируйте — направляйте энергию на созидание.\nЗанимайтесь обустройством собственного дома, периодически расхламляйте пространство. Хобби вроде конструирования или пазлов тоже подойдёт.\nУспех приносит совместный бизнес, планирование, обсуждение стратегии.\nПолезны новые привычки, инновации, периодический отказ от старого, а также тактильность и массаж.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A162"] = 17;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B162"] = "Баланс союза зависит от дружеских отношений между партнёрами, совместного творчества и стремления к известности. Важно раскрывать таланты и природные данные, верить в себя и друг друга, поддерживать и хвалить на пути реализации. Важно помогать раскрываться и другим талантливым людям. Опасность на этом пути — гордыня и отказ от тех, кто был рядом с начала пути. Важно сохранять открытость и тёплое отношение к людям, избегать «звёздной болезни» и высокомерия — они способны спугнуть удачу.\nРекомендации для гармоничного развития отношений:\nЗанимайтесь любимым делом, прислушивайтесь к интуиции. Поддерживайте партнёра в начинаниях, даже необычных.\nПроявляйте себя как автор и творец, не бойтесь демонстрировать таланты, развивайте навыки самопрезентации.\nВыходите в общество, ведите соцсети — можно строить совместное дело на партнёрстве в паре (например, фотограф и визажист).\nНе скрывайте свою жизнь и таланты — вдохновляйте других, это привлечёт единомышленников.\nНе бойтесь мечтать масштабно — чем шире идея, тем больше поддержки она получает.\nПоддерживайте романтику в отношениях, не тратя весь потенциал только на работу и творчество.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A163"] = 18;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B163"] = "Такую пару составляют эмоционально тонкие люди с богатой фантазией. В негативном сценарии это приводит к тому, что партнёры накручивают себя без повода, буквально материализуя негатив мыслями. Важно правильно использовать творческое мышление, избегать обмана и преувеличений внутри пары — такие люди способны настолько красочно описывать события, что верят в них сами. Способности лучше направить продуктивно — на обустройство дома, заботу о детях и близких, творчество. Важна внутренняя работа для создания доверия и уверенности в паре.\nРекомендации для гармоничного развития отношений:\nИзбавьтесь от подозрительности, негативного мышления, ложных страхов — больше доверяйте себе и миру.\nИспользуйте воображение в творчестве — литературе, искусстве, актёрском мастерстве; на бытовом уровне — в создании уютного интерьера, кулинарии.\nДля доверия полезны парная йога, плавание, массаж, спа.\nВозможен интерес к необычным знаниям — эзотерике, нумерологии.\nРождение детей, забота друг о друге и близких, обычные бытовые дела ещё больше сплотят такую пару.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A164"] = 19;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B164"] = "В этой паре важны внутренняя щедрость и вера в успех — скупость или излишняя экономность негативно влияет на союз. Важна сильная позиция мужчины и её признание женщиной. Обоим предстоит научиться не подавлять, а согревать друг друга теплом и щедростью, поддерживать и мотивировать. Важно не только строить успешный союз, но и вести активную жизнь в обществе, заряжая окружающих оптимизмом. Важны мудрое управление и личный пример вместо приказов и давления. Полезно избавляться от эгоизма, проявлять широту души по отношению к детям, близким, подчинённым.\nРекомендации для гармоничного развития отношений:\nНе избегайте ответственности, берите на себя роль главы семьи или дела — заботливо и рассудительно.\nНе подавляйте волю друг друга и других, наоборот — раскрывайте таланты в людях.\nПрислушивайтесь и к разуму, и к интуиции, развивайте творческий подход.\nДействуйте из личных побуждений, а не ради признания, — проявляйте искреннюю щедрость.\nБудьте честны друг с другом, избегайте манипуляций и давления на слабости.\nУделяйте время детям, воспитывайте с удовольствием, проводите время легко и радостно.\nПроявляйте щедрость в мелочах — комплименты, забота, приятные подарки.\nВыходите в общество вместе — получайте заслуженное признание и одаривайте им других.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A165"] = 20;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B165"] = "Партнёры должны быть готовы создать собственный род с традициями и уважением к корням. Ловушка — в неправильном понимании семейных ценностей или их отсутствии, что может создать препятствия в более широких системах, включая государственные. Важно прощать себя и друг друга, позволять другим ошибаться и мыслить иначе. Важно отказаться от шаблонности и постоянного поиска «справедливости» по своим меркам, обид и претензий. Важны поддержание родственных связей и реализация в родительстве.\nРекомендации для гармоничного развития отношений:\nУчитесь понимать причинно-следственные связи, законы высшей справедливости — не судите людей только по своим меркам.\nРазвивайте кругозор, общайтесь с людьми разных взглядов.\nРазвивайте интуицию, возможны необычные способности.\nПоддерживайте отношения с родственниками, устраивайте семейные праздники, храните историю рода — альбомы, записи. Прорабатывайте старые обиды с роднёй.\nУкрепить отношения поможет их развитие — официальный брак, дети, семейный бизнес, с сохранением высоких моральных норм.\nПолезно определить, кто в семье берёт на себя ответственность за укрепление рода.\nТакой паре полезны знакомства с квалифицированными врачами и людьми во власти.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A166"] = 21;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B166"] = "Таким людям важно научиться преодолевать любые границы — географические, культурные, языковые, а также собственные внутренние шаблоны. Важно избегать острых тем, сглаживать конфликты, находить компромиссы. Плохо, если один или оба склонны к спорам и агрессии — для гармонии важно расширять взгляд на мир, не навязывая своё видение другим. Жизнь может подкидывать поездки, путешествия, необходимость узнавать другие культуры и расширять контакты.\nРекомендации для гармоничного развития отношений:\nЛюбить родину и культуру — это правильно, но важно познавать и мир в целом, другие взгляды и религии, с уважением.\nНе ограничивайте себя и других — расширяйте границы через поездки, обмен опытом, международную работу, языки.\nИзбегайте критики своего и чужого устройства жизни — проявляйте дипломатичность, делитесь лучшим из разных культур.\nУчитесь новому вместе, осваивайте технологии и гаджеты.\nНе бойтесь переездов — именно в поездках паре открывается больше возможностей для роста и достатка.\nОбсуждайте границы личных отношений заранее, периодически проговаривая, что устраивает, а что нет.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A167"] = 22;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B167"] = "Таким партнёрам для баланса важно не усложнять отношения, жить легче, с юмором, воспринимая опыт как уроки. Важно учиться экспериментировать, пробовать новое и одновременно брать ответственность за слова и поступки. Важны создание семьи, рождение и воспитание детей при сохранении крепких семейных уз. Предстоит отказаться от легкомыслия и импульсивных решений на эмоциях — истинная свобода в умении контролировать порывы «внутреннего ребёнка», не теряя при этом позитивного взгляда на жизнь, который помогает легко начинать заново и первыми решаться на смелые шаги.\nРекомендации для гармоничного развития отношений:\nБудьте внутренне свободны, избавляйтесь от навязанных шаблонов, но не бунтуйте против естественных правил, подобно детям.\nСтаньте психологически зрелыми и ответственными — заботьтесь друг о друге, воспитывайте детей, показывая пример на своём примере.\nТягу к игре реализуйте через общение с детьми — возможен семейный бизнес: фотостудия, детское кафе, кружки.\nВносите в жизнь больше движения, радости и новых впечатлений, поддерживайте друг в друге лёгкость и юмор.\nПроявляйте творческую жилку даже в обычных делах — вечеринки, розыгрыши, стендап.\nДелитесь смелыми мечтами открыто, будьте свободны в задумках, но продумывайте стратегию по-взрослому.\nВпускайте в жизнь новое — от привычек до технологий — и смело начинайте с нуля при взаимной поддержке.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A169"] = "8.Задачи пары в отношениях";
SHEET_DATA_COMPAT["Данные совместимости"].literals["B169"] = "9.Задачи пары в социуме";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A170"] = 1;
SHEET_DATA_COMPAT["Данные совместимости"].literals["A171"] = 2;
SHEET_DATA_COMPAT["Данные совместимости"].literals["A172"] = 3;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B172"] = "Ваша задача — вместе обустраивать быт, делать окружающее пространство лучше и передавать эти навыки другим. Важно оставаться заботливым, ответственным хозяином, но при этом уметь распределять обязанности и делегировать — так удастся избежать усталости, тревожности и гиперконтроля.\nХорошо, если объединяющими станут домашние дела, обустройство дома, интерьер. Полезен опыт ведения хозяйства. Важны гостеприимство и готовность делиться секретами успеха.\nЗаботьтесь не только о пространстве, но и друг о друге — передавайте семейные ценности, учите младших. Прививайте девочкам традиционные женские навыки, мальчикам — надёжность, ответственность и практические умения.\nСохраняйте оптимизм, любите жизнь во всех проявлениях, балуйте себя простыми радостями — вкусной едой, качественными вещами, комфортом.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A173"] = 4;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B173"] = "Ваша задача — правильно выстроить отношения во всех сферах, от быта до карьеры (если работаете вместе). Проявляйте мудрость, избегая чрезмерного контроля и манипуляций.\nВажно уделять время не только работе, но и грамотно вести дом, находить баланс между заботами и карьерой. Возьмите на себя роль старших в роду — организуйте семейные встречи, наставляйте младших.\nБудьте ответственны сами, не дожидаясь, пока партнёр начнёт требовать. Мотивируйте друг друга, поддерживайте в начинаниях.\nОтлично, если можно расти профессионально вместе — не закрывайте друг другу возможности, а способствуйте карьерному росту. Хорош семейный бизнес — будьте лидерами и организаторами.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A174"] = 5;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B174"] = "Ваша задача — научиться взаимному уважению, по-настоящему узнать и оценить друг друга. Доверяйте, подчёркивайте лучшие стороны партнёра, гордитесь друг другом, помогая развиваться.\nРаскрытию потенциала поможет общая система духовных и жизненных ценностей — учитесь вместе, развивайте друг друга интеллектуально.\nВ такой паре нередок мезальянс — разница в возрасте, статусе, культуре. Совместная жизнь научит взаимодействовать на равных, с уважением к иному мировоззрению.\nИщите себя и своё предназначение всю жизнь, помогайте в этом друг другу. Найдя себя, воспитывайте мудрость, действуйте по высшим законам справедливости.\nВ повседневной жизни вырабатывайте нормы или следите за соблюдением уже сложившихся.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A175"] = 6;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B175"] = "Ваша задача — научиться по-настоящему любить, строить искренние отношения. Создайте крепкий союз, работайте над его качеством, равномерно заботясь о каждом члене семьи.\nВажно быть идеальной семьёй не напоказ, а на деле — поддерживайте тёплую атмосферу дома через совместный уют и красивый интерьер.\nРазвивайте в себе и близких вкус и интерес к искусству — в том числе в быту, следя за собой и своим окружением.\nПолезно бывать в обществе, свободно и непринуждённо раскрывая таланты. Впечатление производят не только манеры, но и искренность в общении. Заводите полезные и перспективные знакомства.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A176"] = 7;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B176"] = "Ваша задача — двигаться в одном направлении, формируя общие цели. Будьте активны, открыты новому и прогрессивному.\nУчитесь управлять собой и своими импульсами — мыслями, эмоциями. Практикуйте осознанность, двигайтесь в естественном темпе, избегая суеты, но и не откладывая решения.\nРеализации предназначения способствуют путешествия и поездки — используйте любой повод. Полезно осваивать новые направления и территории, исследовать, делать открытия.\nНе только размышляйте, но и применяйте всё на практике. Знания часто приходят вдали от дома — привозите их и адаптируйте к своей жизни.\nДелитесь опытом с другими, не замыкая его в узком кругу.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A177"] = 8;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B177"] = "Ваша задача — научиться продуктивно взаимодействовать и разрешать споры. Принимайте решения с позиции высшей справедливости, объективно и взвешенно.\nПроработайте мешающее чувство вины, навязанный долг, гиперответственность. Прощайте ошибки — свои и чужие, не судите категорично. Избавьтесь от излишней обидчивости и упрямства.\nЧтите закон и порядок, по возможности защищайте нуждающихся. Изучайте основы кармы и причинно-следственные связи, чтобы направлять усилия верно.\nФормируйте мудрое, позитивное отношение к жизни — воспринимайте всё как урок. Избегайте жёсткости, проявляйте больше тепла к близким и себе.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A178"] = 9;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B178"] = "Ваша задача — научиться открытости, доверию к миру и всему происходящему. Учите этому других на своём примере свободы и любопытства, а не через контроль.\nПри этом важны здоровые личные границы — уважайте личное пространство партнёра, видя в нём отдельную личность, а не продолжение себя. Тогда рядом с партнёром будет легко, а не одиноко в ожидании полного слияния.\nОткажитесь от неоправданных ограничений себя и других в удовольствиях. Прорабатывайте токсичные установки, мешающие жить как хочется.\nПолезно вместе заниматься наукой, философией, исследованиями — вплоть до эзотерики и необычных способностей.\nСтоит углубиться в одну область, став экспертом, но продолжая развиваться и после.\nДелитесь опытом по запросу, а не навязчиво — как мудрый наставник, желающий сделать знания доступнее.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A179"] = 10;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B179"] = "Ваша задача — раскрыть талант оказываться в нужном месте в нужное время, использовать удачные обстоятельства. Поверить в свою удачу и грамотно ею распоряжаться.\nСмотрите на жизнь с оптимизмом, но сохраняйте трезвость ума, избегая азарта и беспечности. Проявляйте активность вместе — путешествия, события, организация праздников.\nУправляйте эмоциями и мыслями, замечайте вредные шаблоны и меняйте их — не повторяйте одни и те же ошибки в отношениях.\nРазвивайте финансовую грамотность и денежную интуицию, ведите семейный бюджет разумно — без излишеств и без чрезмерной экономии. Учитесь жить по средствам и благодарить за то, что есть.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A180"] = 11;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B180"] = "Ваша задача — научиться сотрудничеству вместо соперничества. Направляйте физическую и внутреннюю силу на общие достижения.\nОвладейте искусством управления эмоциями — избегайте решения вопросов силой. Вырабатывайте терпение, умение слушать и вставать на позицию другого.\nПоддерживайте раскрытие потенциала друг друга — не соревнуйтесь, а дополняйте. Это касается и здоровья, и внешности — здоровый образ жизни, спорт, массаж помогут.\nРазвивайтесь вместе, расширяйте круг единомышленников через совместные тренировки, станьте наставниками для других. Обменивайтесь энергией через подвижные игры и танцы.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A181"] = 12;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B181"] = "Ваша задача — научиться правильному эмоциональному и психологическому взаимодействию. Проявляйте эмпатию, заботьтесь искренне, не ожидая ничего взамен.\nПри этом не становитесь жертвой, не растворяйтесь в желаниях партнёра — соблюдайте баланс между заботой о других и о себе.\nВажный навык — избегать зависимостей и иллюзий, не заниматься самообманом, отличать свои эмоции от чужих. Трезвый взгляд на вещи убережёт от влияния токсичных людей.\nУходите от обесценивания и потребительского отношения. Принятие происходящего поможет выйти из роли жертвы и взять ответственность за свою жизнь — как и отказ от манипуляций и жалости к себе.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A182"] = 13;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B182"] = "Ваша задача — держать руку на пульсе времени, стать проводниками перемен для себя и окружающих. Вовремя отсекайте лишнее, сохраняя ценное и рабочее.\nТрансформации порой болезненны, но их стоит принимать как необходимость — используя кризис как время новых возможностей.\nЭтот опыт поможет преодолеть косность во всех сферах. Пройдя через трудности, вы сможете научить этому других, показав новый путь.\nОбратите внимание на здоровье — своё и партнёра. Избегайте неоправданного риска ради ярких впечатлений — щекотать нервы лучше через осознанную активность, например спорт со страховкой.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A183"] = 14;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B183"] = "Ваша задача — найти баланс в паре и поддерживать его во всём. Стремитесь к гармонии, избегая напрасных тревог и навязчивого желания постоянно быть рядом с партнёром — важно самим закрывать свои эмоциональные потребности.\nПрактикуйте благодарность за то, что уже есть, не претендуя на чужое — ни материально, ни морально.\nВносите в отношения динамику — проявляйте инициативу, развивайте союз. Избегайте рутины, привнося креативность, приятные сюрпризы, новые впечатления через путешествия и мероприятия.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A184"] = 15;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B184"] = "Ваша задача — научиться управлять эмоциональными порывами. Ревность без повода, следование сиюминутным желаниям и жадность способны разрушить и партнёров, и отношения.\nЧтобы избавиться от негативных привычек, важны самоконтроль и осознанность. Созависимые отношения придётся разорвать — только так возможен переход на новый уровень.\nОсобое внимание — чрезмерной сексуальной или энергетической привязанности. Нельзя манипулировать или поддаваться соблазнам, лгать. Духовный рост поможет очистить и гармонизировать союз.\nВажно избегать тёмных практик и любовной магии — при подозрении на негативное влияние извне стоит от него избавиться. Есть риск попасть в сомнительные сообщества — важно прорабатывать тёмную сторону личности и избегать таких компаний.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A185"] = 16;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B185"] = "Ваша задача — грамотно использовать мощь, рождающуюся в союзе, — она должна нести не разрушение, а трансформацию. Контролируйте порывы, не действуйте сгоряча, тщательно обдумывайте шаги.\nПри необходимости расчищайте пространство и мысли от устаревшего — но не ради бездумного разрушения, а чтобы направить энергию на создание нового.\nПаре подходят реальное строительство и реконструкция — своими руками или через инициативу таких процессов. Это касается и нематериального — возрождения ценностей.\nИзбегайте вмешательства в чужие жизни и нарушения границ. Прорабатывайте зависть и желание мстить — разрушение чужого имущества или здоровья негативно отразится на самой паре. Делитесь опытом, помогайте восстанавливать то, что можно сохранить.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A186"] = 17;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B186"] = "Ваша задача — поверить в себя и свою творческую миссию. Найдите таланты и развивайте их без страха быть непонятыми. Заявляйте о себе — в творчестве, науке, обществе, не боясь популярности (избегая при этом гордыни).\nИногда предназначение пары — продвигать других, раскрывая в них таланты. Не бойтесь мечтать масштабно — ваш пример способен вдохновить многих.\nДобившись признания, сохраняйте душевную теплоту в отношениях — сказку можно создать и внутри союза.\nВысокие устремления двигают такую пару вперёд — чем масштабнее цели и больше единомышленников включается в их воплощение, тем шире открывающиеся возможности.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A187"] = 18;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B187"] = "Ваша задача — раскрыть потенциал творческой фантазии и образного мышления. Направляйте умение визуализировать и материализовывать мысли на конструктивные цели, мыслите позитивно.\nИзбегайте привычки накручивать себя и друг друга, прорабатывайте страхи и негативное мышление — у таких пар мысли особенно легко воплощаются. Нельзя лгать или приукрашивать факты фантазией.\nНаправьте воображение на творчество — тексты, дизайн, музыку. В быту создавайте уют для близких, проявляйте таланты в кулинарии и интерьере. Уделяйте силы воспитанию детей и укреплению семьи.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A188"] = 19;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B188"] = "Ваша задача — правильно использовать энергию, рождающуюся в паре. Управляйте эмоциями и силой во благо, вдохновляйте друг друга и окружающих, действуйте смело.\nИспользуйте лидерский потенциал мудро, исходя из интересов подопечных, а не ради подчинения или личной выгоды.\nПомните: власть — это прежде всего ответственность. Справедливо распределяйте ресурсы, раскрывайте в людях лучшее — светите, как солнце, а не обжигайте. Направляйте мягко, убеждением, а не приказами.\nСлужите окружающим бескорыстно, не требуя благодарности. Развивайте творческие способности в паре, обучайте этому и других — организуйте кружки, воспитывайте молодёжь в творческом духе.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A189"] = 20;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B189"] = "Ваша задача — принять себя и друг друга целиком. Учитесь прощать, не осуждать, не критиковать, позволяя другим иметь иное мнение — без обид и претензий.\nНе увлекайтесь чрезмерным правдоискательством — есть законы выше нашего понимания справедливости. Полезно отслеживать причинно-следственные связи, развивать интуицию и эзотерические интересы.\nВажны продолжение рода, семейные традиции, передача опыта поколений. Партнёры способны объединить свои семьи и научить молодёжь чтить традиции. Направьте таланты на воспитание лучших качеств — гордости за род и страну, патриотизма, сохранения моральных устоев.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A190"] = 21;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B190"] = "Ваша задача — развивать дипломатические способности для мирного разрешения острых ситуаций. Учите этому и других, всегда стремясь к компромиссу и взаимопониманию вместо конфликтов.\nПлохо, если кто-то из пары критикует окружающих, культуры, страны или нетерпим к другим взглядам. Наоборот — важно расширять кругозор через путешествия и изучение разных традиций.\nПроявляйте дружелюбие к людям других национальностей и религий, избегайте предвзятости по любому признаку. При этом достойно представляйте свою культуру, сохраняйте и делитесь её ценностями. Возможна деятельность, связанная с международным общением, дипломатией, переводами.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A191"] = 22;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B191"] = "Ваша задача — сформировать ответственное отношение ко всему в жизни, избегая инфантилизма. Будьте взрослыми, сохраняя традиции, а не разрушая их. Передавайте мудрость младшим в роду, уделяя детям достаточно внимания.\nДействуйте обдуманно, без импульсивности и назло. Уходите от легкомыслия — независимость проявляется через зрелость, а свобода не равна анархии. Стремитесь к добрым, дружеским отношениям без бунтарства.\nСвежий взгляд и «детскость» хорошо проявлять в общении с детьми — уделяйте приоритет родительству. Возможна работа, связанная с детьми и семьёй — праздники, фотосъёмка, детские кружки, семейные кафе.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A193"] = "10.Ценность пары";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A194"] = 1;
SHEET_DATA_COMPAT["Данные совместимости"].literals["A195"] = 2;
SHEET_DATA_COMPAT["Данные совместимости"].literals["A196"] = 3;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B196"] = "Ценности пары — достаток, красота и комфорт. Гармония приходит, когда партнёры умеют наслаждаться земными благами, готовы воспитывать детей и создавать материальные ресурсы. Важен чувственный физический контакт — он помогает легко находить общий язык.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A197"] = 4;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B197"] = "Ценности пары — рациональность, надёжность, настойчивость и решительность. Для гармонии важно избегать чрезмерного доминирования и контроля над партнёром.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A198"] = 5;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B198"] = "Ценности пары — закон, традиции, знания, религия, род. Для гармонии важен официальный брак, честные отношения без предательства и измен. Партнёры способны стать друг для друга наставниками.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A199"] = 6;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B199"] = "Ценность — удовольствия, нежность и физическая близость. Гармония наступает, когда партнёры умеют любить и принимать друг друга безусловно, всегда поддерживая друг друга.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A200"] = 7;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B200"] = "Ценности пары — активность, карьера, движение, скорость. Для гармонии важны общие цели и совместное движение к ним, без соперничества.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A201"] = 8;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B201"] = "Ценности пары — справедливость, причинно-следственные связи, ответственность. Для гармонии важны официальный брак, взаимное доверие, ответственность и контроль за собственными мыслями.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A202"] = 9;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B202"] = "Ценность такой пары — глубокое познание друг друга, удовольствие от общества друг друга вне социума. Для гармонии не так важна страсть — на первый план выходят взаимопонимание и духовная близость.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A203"] = 10;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B203"] = "Ценности пары — лёгкость, удача, везение. Для гармонии важно вместе весело проводить время, не подавлять партнёра, не усложнять отношения, оставаться лёгкими и доверять судьбе.";
SHEET_DATA_COMPAT["Данные совместимости"].literals["A204"] = 11;
SHEET_DATA_COMPAT["Данные совместимости"].literals["B204"] = "Ценности пары — спорт, сила, труд, активный отдых. Таким партнёрам полезно вместе заниматься спортом и покорять новые вершины — вместе, будучи сильными, выносливыми и целеустремлёнными, они способны достичь любой цели. Если сила направлена в минус, пару ждут скандалы, поэтому важно направлять энергию в созидание, к общим целям, находить компромиссы, а не тянуть одеяло на себя.";
